import{_ as t,o as a,c as d,aV as o}from"./chunks/framework.BkhZod2m.js";const m=JSON.parse('{"title":"UI 公共 interface","description":"","frontmatter":{},"headers":[],"relativePath":"contracts/ui-public-interface.md","filePath":"contracts/ui-public-interface.md","lastUpdated":null}'),r={name:"contracts/ui-public-interface.md"};function n(i,e,s,c,l,p){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="ui-公共-interface" tabindex="-1">UI 公共 interface <a class="header-anchor" href="#ui-公共-interface" aria-label="Permalink to &quot;UI 公共 interface&quot;">​</a></h1><p>状态：当前权威（新增与变更公共契约的治理口径）。当前可发布的组件及子路径仍以 <code>packages/ui/package.json</code> 的 <code>exports</code>、对应 <code>.d.ts</code> 和发布产物为准。</p><h2 id="qy-所有权" tabindex="-1">Qy 所有权 <a class="header-anchor" href="#qy-所有权" aria-label="Permalink to &quot;Qy 所有权&quot;">​</a></h2><p>业务侧依赖的是 Qy 定义的组件名称、props、emits、slots、expose、默认行为和 tokens。每项新增或变更都必须在 Qy 语义下命名、文档化并以组件测试/声明验证；不能把底层库名称、默认行为或实现对象直接提升为业务契约。</p><table tabindex="0"><thead><tr><th>契约面</th><th>Qy 负责的内容</th><th>不应新增为公共依赖的内容</th></tr></thead><tbody><tr><td>props / defaults</td><td>输入语义、默认值与兼容策略</td><td>Element Plus prop 类型、隐式底层默认值</td></tr><tr><td>emits</td><td>事件名、触发时机和 payload</td><td>厂商私有事件或回调对象</td></tr><tr><td>slots</td><td>Qy 命名、上下文与兼容承诺</td><td>底层组件的未封装 slot 细节</td></tr><tr><td>expose</td><td>Qy 明确承诺的方法和返回语义</td><td>组件实例、私有 DOM、VNode/Node/Store</td></tr><tr><td>tokens</td><td>Qy tokens 及其视觉语义</td><td>业务必须直接使用的 <code>--el-*</code> 变量</td></tr></tbody></table><h2 id="当前实现与历史债务" tabindex="-1">当前实现与历史债务 <a class="header-anchor" href="#当前实现与历史债务" aria-label="Permalink to &quot;当前实现与历史债务&quot;">​</a></h2><p>UI 当前维护 Vue 3 + Element Plus implementation，不是已经多框架兼容的 renderer 层。Element Plus 依赖和内部 import 可以存在；新增公共 API 不得扩大厂商类型、实例、私有 DOM/VNode/Node/Store、私有事件或 <code>--el-*</code> 漏泄。</p><p>现有 <code>packages/ui/qy-input/index.d.ts</code> 的 <code>QyInputProps</code> / <code>QyInputType</code> / <code>autosize</code>，以及 <code>packages/ui/qy-input-number/index.d.ts</code> 的 <code>QyInputNumberProps</code>，仍引用或继承 Element Plus 类型。这是已登记的兼容债务：后续按模块审查、迁移和验证；本文件不宣称其已经框架中立，也不要求本阶段批量修复。</p><h2 id="变更检查" tabindex="-1">变更检查 <a class="header-anchor" href="#变更检查" aria-label="Permalink to &quot;变更检查&quot;">​</a></h2><ol><li>先核对根入口或子路径 exports、对应声明、现有 README 与消费者用法。</li><li>变更 Qy-owned props、emits、slots、expose、defaults 或 tokens 时，补充最小行为/类型证据并保持兼容性口径。</li><li>仅当真实行为差异或复杂边界需要时，建立内部 adapter seam；renderer 决策以 <a href="./../adr/2026-08-06-current-element-implementation-and-future-renderer-seam">当前 Element Plus implementation ADR</a> 为准。</li></ol><p>本契约不决定包版本、构建格式或 npm 解析；这些见 <a href="./package-exports-and-runtime">包 exports 与宿主 runtime</a>。</p>',11)])])}const h=t(r,[["render",n]]);export{m as __pageData,h as default};
